package com.emp.ems;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.Pageable;import org.springframework.http.HttpStatus;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1")
public class LiveMonitorController{private final ActivityRepository activity;private final EmployeeRepository employees;private final AttendanceRepository attendance;private final String bucket,region;LiveMonitorController(ActivityRepository activity,EmployeeRepository employees,AttendanceRepository attendance,@Value("${ems.storage.bucket}")String bucket,@Value("${ems.storage.region}")String region){this.activity=activity;this.employees=employees;this.attendance=attendance;this.bucket=bucket;this.region=region;}record Batch(@NotNull UUID batchId,@NotNull Instant startedAt,@NotNull Instant endedAt,@Min(0)@Max(1000000)int keyboardEvents,@Min(0)@Max(1000000)int mouseEvents,@Min(0)int idleSeconds,@Size(max=1024)String screenshotUrl){}
 @PostMapping("/employee/telemetry")@ResponseStatus(HttpStatus.ACCEPTED)@Transactional Map<String,String> receive(@AuthenticationPrincipal CurrentUser user,@Valid @RequestBody Batch batch){Employee e=employees.lockById(user.id()).orElseThrow();if(activity.existsByEmployeeIdAndBatchId(user.id(),batch.batchId()))return Map.of("status","duplicate");long seconds=Duration.between(batch.startedAt(),batch.endedAt()).getSeconds();if(seconds<1||seconds>86400||batch.idleSeconds()>seconds||batch.endedAt().isAfter(Instant.now().plusSeconds(60))||batch.startedAt().isBefore(Instant.now().minus(Duration.ofDays(2))))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid telemetry window. Submit recent nonnegative summaries.");if(!attendance.covers(user.id(),batch.startedAt(),batch.endedAt()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Activity can only be shared for a clocked-in work period.");if(batch.screenshotUrl()!=null&&!batch.screenshotUrl().isBlank()){String prefix="https://"+bucket+".s3."+region+".amazonaws.com/telemetry/"+user.id()+"/";if(bucket.isBlank()||!batch.screenshotUrl().startsWith(prefix)||batch.screenshotUrl().contains("..")||batch.screenshotUrl().contains("?"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use an asset URL issued by this workspace’s storage service.");}ActivityLog log=new ActivityLog();log.employee=e;log.batchId=batch.batchId();log.startedAt=batch.startedAt();log.endedAt=batch.endedAt();log.logDate=batch.startedAt().atZone(ZoneOffset.UTC).toLocalDate();log.keyboardEvents=batch.keyboardEvents();log.mouseEvents=batch.mouseEvents();log.idleSeconds=batch.idleSeconds();log.screenshotUrl=batch.screenshotUrl();activity.save(log);return Map.of("status","accepted");}
 @GetMapping("/admin/telemetry")@Transactional(readOnly=true)PageResponse<ActivityLog.View> logs(@RequestParam(required=false)UUID employeeId,Pageable page){Pageable p=PeopleController.bounded(page,"startedAt",true);return PageResponse.of((employeeId==null?activity.findAll(p):activity.findByEmployeeId(employeeId,p)).map(ActivityLog::view));}
}
@Component class TelemetryRetention{private final ActivityRepository activity;TelemetryRetention(ActivityRepository activity){this.activity=activity;}@Scheduled(cron="0 0 3 * * *",zone="UTC")@Transactional void prune(){activity.deleteOld(LocalDate.now(ZoneOffset.UTC).minusDays(30));}}
